__NUXT_JSONP__("/sp/about", (function(a){return {data:[{details:{slug:"sp",pageTitle:"¿Quiénes somos? | Mentor Language Institute",pageDescription:"Mentor Language Institute fue fundado en 2002 y está localizado en dos áreas populares: Westwood y Hollywood.",section1:{title:"¿Quiénes somos?",description:["Mentor Language Institute fue fundado en 2002 y está localizado en dos áreas populares: Westwood y Hollywood. \u003Cbr \u002F\u003EAyudamos a estudiantes de todo el mundo a mejorar su Inglés."]},section2:{image:"\u002Fimages\u002Fwhat-is-mli\u002Fabout\u002Fpay-less-for-quality-classes.jpg",title:"Pagá menos por clases de calidad",description:["Valoramos dos cosas: \u003Cb\u003E\"Calidad de educación\"\u003C\u002Fb\u003E  y  \u003Cb\u003E\"precio\".\u003Cb\u003E","El inglés es el idioma global y una herramienta necesaria para la comunicación con personas de todo el mundo. Nuestra esperanza es que los estudiantes internacionales adquieran conocimientos en inglés para tener éxito en el mundo. Por esta razón, nos enfocamos en la calidad de las clases y el bajo precio."]},section3:{image:"\u002Fimages\u002Fwhat-is-mli\u002Fabout\u002Fmli-staff.jpg",title:"Hasta el año 2020, más de 17,000 estudiantes han elegido y se han graduado de MLI.",description:["Ofrecemos ESL (Programa de Inglés General con 6 áreas de habilidades: Gramática\u002FEscritura, Lectura\u002FVocabulario y Comprensión Auditiva\u002FHabla), TOEFL®, IELTS ™ (para estudiantes que desean transferirse a la universidad) e TOEIC®.","Muchos estudiantes también han ido a estudiar a universidades o colleges en los EE.UU. como UCLA, USC y Santa Monica College."],lists:[{link:"\u002Fsp\u002Ffeature",image:a,text:"5 Razones por las que la gente elige MLI"},{link:"\u002Fsp\u002Fcompany",image:a,text:"Información de la compañía"},{link:"\u002Fsp\u002Fimage-gallery",image:a,text:"Foto\u002FGalería de video"}]},dir:"\u002Fabout",path:"\u002Fabout\u002Fsp",extension:".json",createdAt:"2026-10-22T16:31:28.454Z",updatedAt:"2025-05-26T12:06:27.574Z"}}],fetch:{},mutations:void 0}}("\u002Fimages\u002Ficons\u002Fboxed-arrow.svg")));